            for k in keys:
                if k in instance:
                    return instance[k]
            return default
        for k in keys:
            try:
                return instance[k]
            except Exception:
                pass
        try:
            d = instance.__dict__
            for k in keys:
                if k in d:
                    return d[k]
        except Exception:
            pass
        return default

    coords = get_val(["coords", "coord", "locations", "points", "nodes", "node_coords"], None)
    demands = get_val(["demands", "demand"], None)
    capacity = get_val(["capacity", "vehicle_capacity", "cap"], 0)
    depot = get_val(["depot", "depot_id", "depot_index"], 0)

    try:
        capacity = float(capacity)
    except Exception:
        capacity = 0.0

    def coord_of(i):
        if coords is None:
            return (0.0, 0.0)
        try:
            v = coords[i]
            return (float(v[0]), float(v[1]))
        except Exception:
            return (0.0, 0.0)

    def demand_of(i):
        if demands is None:
            return 0.0
        try:
            if is_map(demands):
                return float(demands.get(i, 0.0))
            return float(demands[i])
        except Exception:
            return 0.0

    def dist(a, b):
        ax, ay = coord_of(a)
        bx, by = coord_of(b)
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    customers = []
    if is_map(coords):
        for i in coords.keys():
            if i != depot:
                customers.append(i)
    else:
        try:
            for i in range(len(coords)):
                if i != depot:
                    customers.append(i)
        except Exception:
            if is_map(demands):
                for i in demands.keys():
                    if i != depot:
                        customers.append(i)
            else:
                try:
                    for i in range(len(demands)):
                        if i != depot:
                            customers.append(i)
                except Exception:
                    customers = []

    dx0, dy0 = coord_of(depot)

    def angle_key(i):
        x, y = coord_of(i)
        vx = x - dx0
        vy = y - dy0
        half = 0 if (vy > 0 or (vy == 0 and vx >= 0)) else 1
        if vx == 0:
            slope = 1e100 if vy >= 0 else -1e100
        else:
            slope = vy / vx
        return (half, slope, dist(depot, i), i)

    customers = sorted(customers, key=angle_key)

    def route_load(route):
        s = 0.0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0.0
        c = dist(depot, route[0]) + dist(route[-1], depot)
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        return c

    def two_opt(route):
        n = len(route)
        if n < 4:
            return route[:]
        best = route[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost:
                        best = cand
                        best_cost = c
                        improved = True
                        break
                if improved:
                    break
        return best

    # Greedy sweep construction
    unrouted = customers[:]
    routes = []
    while unrouted:
        seed = unrouted.pop(0)
        route = [seed]
        load = demand_of(seed)
        while True:
            last = route[-1]
            best_idx = -1
            best_key = None
            for idx, c in enumerate(unrouted):
                d = demand_of(c)
                if load + d <= capacity + 1e-12:
                    key = (dist(last, c), dist(depot, c), d, c)
                    if best_key is None or key < best_key:
                        best_key = key
                        best_idx = idx
            if best_idx < 0:
                break
            c = unrouted.pop(best_idx)
            route.append(c)
            load += demand_of(c)
        routes.append(two_opt(route))

    # Improve by relocating customers between routes
    def insert_delta(route, x, pos):
        prev = depot if pos == 0 else route[pos - 1]
        nxt = depot if pos == len(route) else route[pos]
        return dist(prev, x) + dist(x, nxt) - dist(prev, nxt)

    changed = True
    outer = 0
    while changed and outer < 60:
        changed = False
        outer += 1

        # Reorder each route
        for r in range(len(routes)):
            nr = two_opt(routes[r])
            if route_cost(nr) + 1e-12 < route_cost(routes[r]):
                routes[r] = nr
                changed = True

        loads = [route_load(r) for r in routes]

        # Relocate improvements
        for a in range(len(routes)):
            ra = routes[a]
            if not ra:
                continue
            ia = 0
            while ia < len(ra):
                x = ra[ia]
                dx = demand_of(x)
                best_move = None
                old_cost = route_cost(ra)
                for b in range(len(routes)):
                    rb = routes[b]
                    if a == b:
                        continue
                    if loads[b] + dx > capacity + 1e-12:
                        continue
                    for pos in range(len(rb) + 1):
                        new_ra = ra[:ia] + ra[ia + 1:]
                        new_rb = rb[:pos] + [x] + rb[pos:]
                        new_cost = route_cost(new_ra) + route_cost(new_rb)
                        if new_cost + 1e-12 < old_cost + route_cost(rb):
                            cand = (new_cost, b, pos)
                            if best_move is None or cand < best_move:
                                best_move = cand
                if best_move is not None:
                    _, b, pos = best_move
                    rb = routes[b]
                    ra = routes[a]
                    ra.pop(ia)
                    routes[a] = ra
                    routes[b] = rb[:pos] + [x] + rb[pos:]
                    changed = True
                    loads[a] -= dx
                    loads[b] += dx
                    if not ra:
                        routes[a] = []
                    break
                ia += 1

        # Remove empty routes
        routes = [r for r in routes if r]

    # Final cleanup and deterministic ordering
    final_routes = []
    for r in routes:
        if r:
            final_routes.append(two_opt(r))

    # Ensure every customer appears exactly once; repair if needed
    seen = {}
    for r in final_routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = []
    for c in customers:
        if seen.get(c, 0) == 0:
            missing.append(c)

    if missing:
        # Insert missing customers into feasible positions greedily
        for x in missing:
            dx = demand_of(x)
            best = None
            best_r = -1
            best_p = -1
            # try existing routes
            for r in range(len(final_routes)):
                if route_load(final_routes[r]) + dx > capacity + 1e-12:
                    continue
                rr = final_routes[r]
                for p in range(len(rr) + 1):
                    delta = insert_delta(rr, x, p)
                    cand = (delta, r, p)
                    if best is None or cand < best:
                        best = cand
                        best_r = r
                        best_p = p
            if best is None:
                final_routes.append([x])
            else:
                rr = final_routes[best_r]
                final_routes[best_r] = rr[:best_p] + [x] + rr[best_p:]

    # Remove duplicates if any by keeping first occurrence
    used = {}
    cleaned = []
    for r in final_routes:
        nr = []
        load = 0.0
        for c in r:
            if used.get(c, 0) == 0:
                d = demand_of(c)
                if load + d <= capacity + 1e-12:
                    nr.append(c)
                    used[c] = 1
                    load += d
        if nr:
            cleaned.append(nr)

    # Add any still-missing customers as singleton routes if needed
    for c in customers:
        if used.get(c, 0) == 0:
            cleaned.append([c])
            used[c] = 1

    return cleaned
